/** MIT. Retain the native facilitator receipt across the official MCP wrapper. */
import {AsyncLocalStorage} from 'node:async_hooks';

const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const RECEIPT_KEY = 'x402/payment-response';
const MAX_RECEIPT_BYTES = 48 * 1024;

/** Compact quote metadata; the complete MCP result retains every original field. */
export function paymentResponseSummary(receipt) {
  if (!plain(receipt)) return null;
  const result = {success:receipt.success === true};
  const limits = {network:128, transaction:256, payer:128, errorReason:512, errorMessage:4096};
  const truncated = [];
  for (const [name, limit] of Object.entries(limits)) {
    if (['errorReason','errorMessage'].includes(name) && receipt[name] === undefined) continue;
    result[name] = typeof receipt[name] === 'string' ? receipt[name].slice(0, limit) : null;
    if (typeof receipt[name] === 'string' && receipt[name].length > limit) truncated.push(name);
  }
  if (truncated.length) result.truncatedFields = truncated;
  return result;
}

/**
 * The native client and official resource server keep their original behavior.
 * Only their returned public SettleResponse is observed. Per-call async context
 * prevents concurrent MCP sessions from receiving another caller's receipt.
 */
export function createSettlementReceiptCapture(facilitator) {
  const context = new AsyncLocalStorage();
  const client = Object.freeze({
    getSupported:(...args) => facilitator.getSupported(...args),
    verify:(...args) => facilitator.verify(...args),
    async settle(...args) {
      const receipt = await facilitator.settle(...args);
      const current = context.getStore();
      if (current) current.receipt = receipt;
      return receipt;
    },
  });
  return Object.freeze({client,
    run:(observation, operation) => context.run(observation, operation),
    attach(result, observation) {
      // An existing SDK receipt is authoritative; preserve the complete result.
      if (!plain(result) || result._meta?.[RECEIPT_KEY] !== undefined ||
          !plain(observation.receipt) || typeof observation.receipt.success !== 'boolean') return result;
      let receipt;
      try {
        const bytes = JSON.stringify(observation.receipt);
        if (Buffer.byteLength(bytes) > MAX_RECEIPT_BYTES) return result;
        receipt = JSON.parse(bytes);
      } catch { return result; }
      // x402/mcp 2.28 returns a new PaymentRequired error on failed settlement
      // and omits this native receipt. Restore metadata without changing that
      // error, invoking a handler again, or calling the facilitator again.
      return {...result, _meta:{...result._meta, [RECEIPT_KEY]:receipt}};
    },
  });
}

// MIT. Read only the native, direct required-query declaration; not a schema engine.
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const unsupported = () => Object.assign(new Error(
  'Required query names must be a direct list of up to 30 unique, nonempty names of at most 100 characters without control characters.'
), { code: 'INPUT_SCHEMA_UNSUPPORTED' });

export function requiredQueryKeys(bazaarSchema) {
  let query = bazaarSchema;
  for (const key of ['properties', 'input', 'properties', 'queryParams']) {
    if (!record(query) || !Object.hasOwn(query, key)) return [];
    query = query[key];
  }
  if (!record(query) || !Object.hasOwn(query, 'required')) return [];
  const required = query.required;
  if (!Array.isArray(required) || required.length > 30) throw unsupported();
  const keys = [];
  const seen = new Set();
  for (const key of required) {
    if (typeof key !== 'string' || key.length === 0 || key.length > 100 ||
        /[\u0000-\u001f\u007f]/.test(key) || seen.has(key)) throw unsupported();
    seen.add(key);
    keys.push(key);
  }
  return keys;
}

/** MIT. Detached, cursor-paginated views of the broker's original quote records. */
export function historyPage(records, { status, limit = 25, cursor } = {}, project = value => structuredClone(value)) {
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100 ||
      (status !== undefined && (typeof status !== 'string' || status.length > 64)))
    throw Object.assign(new TypeError('Invalid quote history filter'), { code: 'INVALID_PARAMS' });
  let boundary;
  if (cursor !== undefined) {
    try {
      if (typeof cursor !== 'string' || cursor.length > 256 || !/^[A-Za-z0-9_-]+$/.test(cursor)) throw Error();
      boundary = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
      if (!Number.isSafeInteger(boundary.createdAt) || typeof boundary.quoteId !== 'string' || boundary.quoteId.length !== 36)
        throw Error();
    } catch { throw Object.assign(new TypeError('Invalid quote history cursor'), { code: 'INVALID_PARAMS' }); }
  }
  const all = [...records].filter(row => status === undefined || row.status === status)
    .sort((a, b) => b.createdAt - a.createdAt || b.quoteId.localeCompare(a.quoteId));
  const remaining = all.filter(row => !boundary || row.createdAt < boundary.createdAt ||
    (row.createdAt === boundary.createdAt && row.quoteId < boundary.quoteId));
  const page = remaining.slice(0, limit), last = page.at(-1);
  return { quotes: page.map(project), total: all.length,
    nextCursor: remaining.length > page.length ? Buffer.from(JSON.stringify({ createdAt: last.createdAt, quoteId: last.quoteId })).toString('base64url') : null };
}

/** MIT. Private, single-writer SQLite quote storage for the original MCP broker. */
import { DatabaseSync } from 'node:sqlite';
import { closeSync, lstatSync, mkdirSync, openSync, realpathSync } from 'node:fs';
import { isAbsolute, join } from 'node:path';
import { createHash } from 'node:crypto';
import { isDeepStrictEqual as same } from 'node:util';
import { validateMcpInvocation } from './remote-mcp.mjs';

const STATES = new Set(['PREVIEWED', 'APPROVAL_PENDING', 'EXECUTING', 'CANCEL_REQUESTED',
  'CANCELLED', 'EXPIRED', 'FREE_SUCCESS', 'PROBE_REJECTED', 'CONFIRMED_BY_SERVER',
  'INDETERMINATE', 'REJECTED', 'INTERRUPTED', 'CONFIG_CHANGED']);
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const error = (code, message) => Object.assign(new Error(message), { code });
