          value.signedRequestDispatched ? 1 : 0, value.attempts);
      this.#db.exec('COMMIT;');
    } catch (failure) {
      try { this.#db.exec('ROLLBACK;'); } catch { /* retain original failure */ }
      throw failure;
    }
