      .map(row => ({ ...row, signedRequestDispatched: row.signedRequestDispatched === 1 }));
  }

  close() {
    if (this.#closed) return;
    this.#closed = true;
    try { this.#db?.close(); }
    finally { this.#owner?.close(); }
  }
}

