// One budget covers all alternatives and recursive instance descent in a validation.
const MAX_SCHEMA_EVALUATIONS = 100_000;
const SCHEMA_KEYS = new Set([
  '$schema', '$id', '$ref', '$defs', 'definitions', 'type', 'properties', 'required',
  'additionalProperties', 'items', 'const', 'enum', 'anyOf', 'allOf', 'oneOf', 'not', 'propertyNames',
  'minLength', 'maxLength', 'minimum', 'maximum', 'minItems', 'maxItems',
  'uniqueItems', 'title', 'description', 'default', 'examples',
  'exclusiveMinimum', 'exclusiveMaximum', 'pattern', 'format', 'readOnly', 'writeOnly', 'deprecated', '$comment',
]);
const TYPES = {
  object: plain,
  array: Array.isArray,
  string: value => typeof value === 'string',
  number: value => typeof value === 'number' && Number.isFinite(value),
  integer: value => Number.isSafeInteger(value),
  boolean: value => typeof value === 'boolean',
  null: value => value === null,
};

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (plain(value)) return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));
  return value;
}

function equal(a, b) { return JSON.stringify(canonical(a)) === JSON.stringify(canonical(b)); }

function inspectSchema(schema, depth = 0, state = { nodes: 0, schemas: new WeakSet(), references: [] }) {
  state.nodes += 1;
  if (state.nodes > 512 || depth > 16) return 'SCHEMA_COMPLEXITY_LIMIT';
  if (schema === true || schema === false) return null;
  if (!plain(schema)) return 'SCHEMA_NODE_INVALID';
  if (state.schemas.has(schema)) return null;
  state.schemas.add(schema);
  for (const [key, value] of Object.entries(schema)) {
    if (!SCHEMA_KEYS.has(key)) return `SCHEMA_KEYWORD_UNSUPPORTED:${key}`;
    if ((key === '$ref' || key === '$id') && (typeof value !== 'string' || !value.startsWith('#'))) {
      return 'SCHEMA_EXTERNAL_REFERENCE';
    }
    if (key === '$ref') state.references.push(value);
    // A malformed assertion keyword cannot be treated as an absent assertion.
    // Network-supplied schemas must fail closed rather than over-admit info.
    if (key === 'type') {
      const types = Array.isArray(value) ? value : [value];
      if (!types.length || types.some(t => typeof t !== 'string' || !Object.hasOwn(TYPES, t)) ||
          new Set(types).size !== types.length) return 'SCHEMA_TYPE_INVALID';
    }
    if (['minLength', 'maxLength', 'minItems', 'maxItems'].includes(key) &&
        (!Number.isSafeInteger(value) || value < 0)) return 'SCHEMA_' + key.toUpperCase() + '_INVALID';
    if (['minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum'].includes(key) &&
        (typeof value !== 'number' || !Number.isFinite(value))) return 'SCHEMA_' + key.toUpperCase() + '_INVALID';
    if (key === 'uniqueItems' && typeof value !== 'boolean') return 'SCHEMA_UNIQUEITEMS_INVALID';
    if (key === 'required' && (!Array.isArray(value) ||
        value.some(k => typeof k !== 'string') || new Set(value).size !== value.length))
      return 'SCHEMA_REQUIRED_INVALID';
    if (key === 'enum' && (!Array.isArray(value) || value.length === 0))
      return 'SCHEMA_ENUM_INVALID';
    if (['title', 'description', 'format', '$comment'].includes(key) && typeof value !== 'string')
      return 'SCHEMA_' + key.toUpperCase() + '_INVALID';
    if (['readOnly', 'writeOnly', 'deprecated'].includes(key) && typeof value !== 'boolean')
      return 'SCHEMA_' + key.toUpperCase() + '_INVALID';
    if (key === 'pattern') {
      try { compileSchemaPattern(value); } catch (error) { return error.message; }
    }
    if (key === 'examples' && !Array.isArray(value)) return 'SCHEMA_EXAMPLES_INVALID';
    if (['properties', '$defs', 'definitions'].includes(key)) {
      if (!plain(value)) return `SCHEMA_${key.toUpperCase()}_INVALID`;
      for (const child of Object.values(value)) {
        const error = inspectSchema(child, depth + 1, state); if (error) return error;
      }
    } else if (['items', 'additionalProperties', 'not', 'propertyNames'].includes(key)) {
      if (!plain(value) && typeof value !== 'boolean')
        return 'SCHEMA_' + key.toUpperCase() + '_INVALID';
      const error = inspectSchema(value, depth + 1, state); if (error) return error;
    } else if (['anyOf', 'allOf', 'oneOf'].includes(key)) {
      if (!Array.isArray(value) || value.length === 0) return `SCHEMA_${key.toUpperCase()}_INVALID`;
      for (const child of value) {
        const error = inspectSchema(child, depth + 1, state); if (error) return error;
      }
    }
  }
  return null;
}

function resolvePointer(root, ref) {
  if (ref === '#') return root;
  if (!ref.startsWith('#/')) throw new TypeError('SCHEMA_LOCAL_REFERENCE_INVALID');
  let node = root;
  for (const raw of ref.slice(2).split('/')) {
    const key = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (!plain(node) || !Object.hasOwn(node, key)) throw new TypeError('SCHEMA_LOCAL_REFERENCE_MISSING');
    node = node[key];
  }
  return node;
}

function validateNode(value, schema, root, path = '$', refs = new Set(), depth = 0, evaluation = { nodes: 0 }) {
  if (++evaluation.nodes > MAX_SCHEMA_EVALUATIONS) throw new TypeError('SCHEMA_EVALUATION_LIMIT');
  if (depth > 512) throw new TypeError('SCHEMA_EVALUATION_DEPTH_LIMIT');
  if (schema === true) return [];
  if (schema === false) return [`${path}:false_schema`];
  if (!plain(schema)) throw new TypeError('SCHEMA_NODE_INVALID');
  if (schema.$ref !== undefined) {
    if (refs.has(schema.$ref)) throw new TypeError('SCHEMA_REFERENCE_CYCLE');
    const next = new Set(refs); next.add(schema.$ref);
    const errors = validateNode(value, resolvePointer(root, schema.$ref), root, path, next, depth + 1, evaluation);
    if (errors.length) return errors;
    // Draft 2020-12 applies adjacent keywords as well as the referenced schema.
    // Keep the reference stack local to its branch: a sibling can reuse it.
  }
  if (schema.const !== undefined && !equal(value, schema.const)) return [`${path}:const`];
  if (Array.isArray(schema.enum) && !schema.enum.some(item => equal(value, item))) return [`${path}:enum`];
  if (schema.type !== undefined) {
    const expected = Array.isArray(schema.type) ? schema.type : [schema.type];
    if (!expected.some(type => TYPES[type]?.(value))) return [`${path}:type`];
  }
  for (const group of ['allOf', 'anyOf', 'oneOf']) {
    if (schema[group] !== undefined && !Array.isArray(schema[group])) return [`${path}:${group}_invalid`];
  }
  if (schema.allOf) {
    const errors = schema.allOf.flatMap(part => validateNode(value, part, root, path, refs, depth + 1, evaluation));
    if (errors.length) return errors;
  }
  if (schema.anyOf && !schema.anyOf.some(part => validateNode(value, part, root, path, refs, depth + 1, evaluation).length === 0)) return [`${path}:anyOf`];
  if (schema.oneOf && schema.oneOf.filter(part => validateNode(value, part, root, path, refs, depth + 1, evaluation).length === 0).length !== 1) return [`${path}:oneOf`];
  if (Object.hasOwn(schema, 'not')) {
    const errors = validateNode(value, schema.not, root, path, refs, depth + 1, evaluation);
    if (!errors.length) return [`${path}:not`];
  }
  if (typeof value === 'string' && schema.pattern !== undefined && !compileSchemaPattern(schema.pattern).test(value))
    return [`${path}:pattern`];
  if (typeof value === 'string' &&
      (Number.isSafeInteger(schema.minLength) || Number.isSafeInteger(schema.maxLength))) {
    // JSON Schema counts Unicode code points, not UTF-16 code units or graphemes.
    // Iterate without allocating a second array proportional to the string size.
    let length = 0;
    for (const character of value) length++;
    if (Number.isSafeInteger(schema.minLength) && length < schema.minLength) return [`${path}:minLength`];
    if (Number.isSafeInteger(schema.maxLength) && length > schema.maxLength) return [`${path}:maxLength`];
  }
  if (typeof value === 'number') {
    if (typeof schema.minimum === 'number' && value < schema.minimum) return [`${path}:minimum`];
    if (typeof schema.maximum === 'number' && value > schema.maximum) return [`${path}:maximum`];
    if (typeof schema.exclusiveMinimum === 'number' && value <= schema.exclusiveMinimum) return [`${path}:exclusiveMinimum`];
    if (typeof schema.exclusiveMaximum === 'number' && value >= schema.exclusiveMaximum) return [`${path}:exclusiveMaximum`];
  }
  if (Array.isArray(value)) {
    if (Number.isSafeInteger(schema.minItems) && value.length < schema.minItems) return [`${path}:minItems`];
    if (Number.isSafeInteger(schema.maxItems) && value.length > schema.maxItems) return [`${path}:maxItems`];
    if (schema.uniqueItems === true && new Set(value.map(item => JSON.stringify(canonical(item)))).size !== value.length) return [`${path}:uniqueItems`];
    if (schema.items !== undefined) {
      for (let index = 0; index < value.length; index++) {
        const errors = validateNode(value[index], schema.items, root, `${path}[${index}]`, new Set(), depth + 1, evaluation); if (errors.length) return errors;
      }
    }
  }
  if (plain(value)) {
    if (schema.required !== undefined && (!Array.isArray(schema.required) || schema.required.some(key => typeof key !== 'string'))) return [`${path}:required_invalid`];
    for (const key of schema.required ?? []) if (!Object.hasOwn(value, key)) return [`${path}.${key}:required`];
    const properties = plain(schema.properties) ? schema.properties : {};
    for (const [key, item] of Object.entries(value)) {
      if (Object.hasOwn(schema, 'propertyNames')) {
        const errors = validateNode(key, schema.propertyNames, root, `${path}.${key}:propertyName`, new Set(), depth + 1, evaluation);
        if (errors.length) return errors;
      }
      if (Object.hasOwn(properties, key)) {
        const errors = validateNode(item, properties[key], root, `${path}.${key}`, new Set(), depth + 1, evaluation); if (errors.length) return errors;
      } else if (schema.additionalProperties === false) return [`${path}.${key}:additionalProperties`];
      else if (plain(schema.additionalProperties) || typeof schema.additionalProperties === 'boolean') {
        const errors = validateNode(item, schema.additionalProperties, root, `${path}.${key}`, new Set(), depth + 1, evaluation); if (errors.length) return errors;
      }
    }
  }
  return [];
}

export function validateBazaarExtension(extension) {
  if (!plain(extension?.info) || !plain(extension?.schema)) return { ok: false, reason: 'BAZAAR_EXTENSION_INVALID' };
  let bytes;
  try { bytes = Buffer.byteLength(JSON.stringify(extension.schema), 'utf8'); }
  catch { return { ok: false, reason: 'SCHEMA_NOT_SERIALIZABLE' }; }
  if (bytes > 32_768) return { ok: false, reason: 'SCHEMA_SIZE_LIMIT' };
  if (extension.schema.$schema !== DRAFT) return { ok: false, reason: 'SCHEMA_DRAFT_REQUIRED' };
  const state = { nodes: 0, schemas: new WeakSet(), references: [] };
  const inspection = inspectSchema(extension.schema, 0, state);
  if (inspection) return { ok: false, reason: inspection };
  try {
    // Check every referenced target, including alternatives not taken by this instance.
    // This follows schema nodes once, so finite recursive message definitions stay valid.
    const checked = new Set();
    for (let index = 0; index < state.references.length; index++) {
      const ref = state.references[index];
      if (checked.has(ref)) continue;
      checked.add(ref);
      const invalid = inspectSchema(resolvePointer(extension.schema, ref), 0, state);
      if (invalid) return { ok: false, reason: invalid };
    }
    const errors = validateNode(extension.info, extension.schema, extension.schema);
    return errors.length ? { ok: false, reason: 'INFO_SCHEMA_MISMATCH', errors } : { ok: true };
  } catch (error) {
    // Schema errors propagate through all combinators instead of becoming an instance mismatch.
    return { ok: false, reason: error.message };
  }
}

// MIT — SF-50: pin a Bazaar-discovered x402 v2 offer before any wallet authorization.
// No signing, transport, settlement, seller attestation, or funds access.
import { createHash } from 'node:crypto';

const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const reject = reason => ({ ok: false, reason });
const METHODS = new Set(['GET', 'HEAD', 'DELETE', 'POST', 'PUT', 'PATCH']);
const MONEY_KEYS = ['scheme', 'network', 'asset', 'payTo', 'amount', 'maxTimeoutSeconds', 'extra'];

function canonical(value) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'number' && Number.isFinite(value)) return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (!object(value)) throw new TypeError('Invalid JSON value');
  const names = Object.keys(value).sort();
  return '{' + names.map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
}
const digest = value => createHash('sha256').update(canonical(value)).digest('hex');

function checkedURL(value) {
  if (typeof value !== 'string' || value.length > 4096 || /[\x00-\x20\x7f\\]/.test(value)) throw new TypeError('Unsafe resource URL');
  const url = new URL(value);
  if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password || url.hash || url.href !== value) {
    throw new TypeError('Invalid canonical resource URL');
  }
  return url.href;
}

function termsOf(acceptance) {
  if (!object(acceptance)) throw new TypeError('Payment option required');
  for (const key of ['scheme', 'network', 'asset', 'payTo']) {
    if (typeof acceptance[key] !== 'string' || !acceptance[key] || acceptance[key].length > 512) {
      throw new TypeError(`Invalid ${key}`);
    }
  }
  if (typeof acceptance.amount !== 'string' || !/^[1-9][0-9]*$/.test(acceptance.amount)) {
    throw new TypeError('Atomic amount must be a positive decimal string');
  }
  if (acceptance.amount.length > 78) throw new RangeError('Atomic amount too long');
  const timeout = acceptance.maxTimeoutSeconds === undefined ? null : acceptance.maxTimeoutSeconds;
  if (timeout !== null && (!Number.isSafeInteger(timeout) || timeout <= 0)) throw new TypeError('Invalid timeout');
  const extra = acceptance.extra === undefined ? null : acceptance.extra;
  if (extra !== null && !object(extra)) throw new TypeError('Invalid extra terms');
  const result = {
    scheme: acceptance.scheme, network: acceptance.network, asset: acceptance.asset,
    payTo: acceptance.payTo, amount: acceptance.amount, maxTimeoutSeconds: timeout,
    extra: extra === null ? null : structuredClone(extra)
  };
  if (canonical(result).length > 16384) throw new RangeError('Payment terms too large');
  return result;
}

function identityOf(listing) {
  const url = checkedURL(listing?.resource?.url);
  const input = listing?.extensions?.bazaar?.info?.input;
  if (!object(input)) throw new TypeError('Bazaar discovery input required');
  if (input.type === 'http' && METHODS.has(input.method)) {
    return { resourceURL: url, kind: 'http', method: input.method };
  }
  if (input.type === 'mcp' && typeof input.toolName === 'string' && /^[A-Za-z0-9_.-]{1,128}$/.test(input.toolName)) {
    return { resourceURL: url, kind: 'mcp', toolName: input.toolName };
  }
  throw new TypeError('Invalid Bazaar HTTP/MCP identity');
}

/**
 * Accepts one REAL BazaarCatalog.list/search record. Selection is a client-local
 * immutable intention, not a provider signature or proof of seller ownership.
 */
export function bindDiscoveryQuote({ listing, acceptanceIndex = 0, observedAtMs = Date.now(), ttlMs = 60000 }) {
  if (!object(listing) || !Array.isArray(listing.accepts) ||
      !Number.isSafeInteger(acceptanceIndex) || acceptanceIndex < 0 || acceptanceIndex >= listing.accepts.length) {
    throw new TypeError('Selected Bazaar payment option missing');
  }
  if (!Number.isSafeInteger(observedAtMs) || observedAtMs < 0 ||
      !Number.isSafeInteger(ttlMs) || ttlMs <= 0 || ttlMs > 3600000) {
    throw new RangeError('Invalid observation time or quote TTL');
  }
  const details = {
    version: 1, identity: identityOf(listing), terms: termsOf(listing.accepts[acceptanceIndex]),
    observedAtMs, expiresAtMs: observedAtMs + ttlMs
  };
  if (!Number.isSafeInteger(details.expiresAtMs)) throw new RangeError('Invalid expiry');
  const quote = { ...details, quoteId: digest(details) };
  return Object.freeze({ ...quote, identity: Object.freeze(quote.identity), terms: Object.freeze(quote.terms) });
}

/**
 * Must be called with the actual invocation and actual 402 PaymentRequired before
 * any signer is invoked. Returns only preflight approval + selected x402 terms.
 */
export function reviewPaymentRequired({ quote, paymentRequired, invocation, nowMs = Date.now() }) {
  if (!object(quote) || !object(quote.identity) || !object(quote.terms) ||
      quote.version !== 1 || typeof quote.quoteId !== 'string') return reject('QUOTE_INVALID');
  try {
    const { quoteId, ...rest } = quote;
    if (digest(rest) !== quoteId) return reject('QUOTE_CHANGED');
  } catch { return reject('QUOTE_INVALID'); }
  if (!Number.isSafeInteger(nowMs)) return reject('CLOCK_INVALID');
  if (nowMs < quote.observedAtMs || nowMs >= quote.expiresAtMs) return reject('QUOTE_EXPIRED');
  if (!object(invocation) || invocation.kind !== quote.identity.kind ||
      invocation.resourceURL !== quote.identity.resourceURL) return reject('INVOCATION_RESOURCE_CHANGED');
  if (quote.identity.kind === 'http' && invocation.method !== quote.identity.method) return reject('INVOCATION_METHOD_CHANGED');
  if (quote.identity.kind === 'mcp' && invocation.toolName !== quote.identity.toolName) return reject('INVOCATION_TOOL_CHANGED');
  if (!object(paymentRequired) || paymentRequired.x402Version !== 2 || !Array.isArray(paymentRequired.accepts)) {
    return reject('X402_V2_REQUIRED');
  }
  if (paymentRequired.resource?.url !== quote.identity.resourceURL) return reject('CHALLENGE_RESOURCE_CHANGED');
  const offeredInput = paymentRequired.extensions?.bazaar?.info?.input;
  if (offeredInput !== undefined) {
    if (!object(offeredInput) || offeredInput.type !== quote.identity.kind) return reject('CHALLENGE_TYPE_CHANGED');
    if (quote.identity.kind === 'http' && offeredInput.method !== quote.identity.method) return reject('CHALLENGE_METHOD_CHANGED');
    if (quote.identity.kind === 'mcp' && offeredInput.toolName !== quote.identity.toolName) return reject('CHALLENGE_TOOL_CHANGED');
  }
  let route = false, recipient = false, amount = false;
  for (const offered of paymentRequired.accepts) {
    let terms;
    try { terms = termsOf(offered); } catch { continue; }
    const expected = quote.terms;
    if (terms.scheme !== expected.scheme || terms.network !== expected.network || terms.asset !== expected.asset) continue;
    route = true;
    if (terms.payTo !== expected.payTo) continue;
    recipient = true;
    if (terms.amount !== expected.amount) continue;
    amount = true;
    if (terms.maxTimeoutSeconds !== expected.maxTimeoutSeconds || canonical(terms.extra) !== canonical(expected.extra)) continue;
    // Downstream signers must receive ONLY the payment facts reviewed here.
    // Additional top-level fields in an untrusted 402 are not authorized.
    const accepted = {
      scheme: terms.scheme, network: terms.network, asset: terms.asset,
      payTo: terms.payTo, amount: terms.amount,
    };
    if (Object.hasOwn(offered, 'maxTimeoutSeconds')) accepted.maxTimeoutSeconds = terms.maxTimeoutSeconds;
    if (Object.hasOwn(offered, 'extra')) accepted.extra = structuredClone(terms.extra);
    return { ok: true, quoteId: quote.quoteId, accepted };
  }
  return reject(!route ? 'PAYMENT_ROUTE_CHANGED' : !recipient ? 'RECIPIENT_CHANGED' : !amount ? 'AMOUNT_CHANGED' : 'PAYMENT_TERMS_CHANGED');
}

/**
 * Stellar Forge SF-28 - x402 Bazaar route and resource identity.
 * Pure, dependency-free catalog-ingestion guard, not a payment verifier.
 * Baseline: x402-foundation/x402@7f2b2f1f77fa5317615735e3378a6fad41cccb4e
 * specs/extensions/bazaar.md blob 442708e76d5a129e0c1393471d8ed71e3604c94e.
 * Upstream already fixes multi-encoded traversal (TS #3213, Go #3441).
 */
const RAW_TEMPLATE = /^\/[A-Za-z0-9_/:.\-~%]+$/;
const DECODED_TEMPLATE = /^\/[A-Za-z0-9_/:.\-~]+$/;
const PARAM = /^:([A-Za-z_][A-Za-z0-9_]*)$/;
const METHODS = new Set(['GET','HEAD','DELETE','POST','PUT','PATCH']);
const fail = reason => ({ok:false,reason});

/** Align five bounded decoding passes with the pinned TS/Go source. */
function fixedDecode(raw) {
  let value = raw;
  for (let pass=0; pass<5; pass++) {
    let next;
    try { next=decodeURIComponent(value); }
    catch { return fail('INVALID_PERCENT_ENCODING'); }
    if(next === value) return {ok:true,value};
    value=next;
  }
  return fail('ENCODING_DEPTH_EXCEEDED');
}

/** Stricter catalog key policy layered after the canonical SDK validator. */
export function inspectRouteTemplate(value) {
  if(typeof value!=='string'||!value) return fail('TEMPLATE_MISSING');
  if(value.length>2048) return fail('TEMPLATE_TOO_LONG');
  if(!value.startsWith('/')) return fail('TEMPLATE_NOT_ABSOLUTE');
  if(!RAW_TEMPLATE.test(value)) return fail('TEMPLATE_UNSAFE_CHAR');
  const decoded=fixedDecode(value);
  if(!decoded.ok) return fail('TEMPLATE_'+decoded.reason);
  const path=decoded.value;
  if(path.includes('..')) return fail('TEMPLATE_TRAVERSAL');
  if(path.includes('://')) return fail('TEMPLATE_SCHEME_INJECTION');
  if(!DECODED_TEMPLATE.test(path)) return fail('TEMPLATE_DECODED_UNSAFE_CHAR');
  if(value.split('/').length!==path.split('/').length) return fail('TEMPLATE_ENCODED_SEPARATOR');
  const names=new Set();
  for(const part of path.slice(1).split('/')) {
    if(!part||part==='.') return fail('TEMPLATE_AMBIGUOUS_SEGMENT');
    if(!part.includes(':')) continue;
    const match=PARAM.exec(part);
    if(!match) return fail('TEMPLATE_PARAM_SYNTAX');
    if(names.has(match[1])) return fail('TEMPLATE_DUPLICATE_PARAM');
    names.add(match[1]);
  }
  return {ok:true,canonicalPath:path,paramNames:[...names]};
}

/** Inspect the original URL before WHATWG URL can normalize away dot segments. */
export function inspectResourceURL(input) {
  if(typeof input!=='string'||!input) return fail('RESOURCE_URL_MISSING');
  if(input.length>4096) return fail('RESOURCE_URL_TOO_LONG');
  if(/[\x00-\x20\x7f\\]/.test(input)) return fail('RESOURCE_URL_UNSAFE_CHAR');
  const prefix=/^https?:\/\/([^/?#]*)/i.exec(input);
  if(!prefix) return fail('RESOURCE_URL_SCHEME');
  if(prefix[1].includes('@')) return fail('RESOURCE_URL_USERINFO');
  if(input.includes('#')) return fail('RESOURCE_URL_FRAGMENT');
  const rawPath=input.slice(prefix[0].length).split(/[?#]/,1)[0]||'/';
  if(!rawPath.startsWith('/')) return fail('RESOURCE_PATH_NOT_ABSOLUTE');
  for(const segment of rawPath.split('/')) {
    if(!segment) continue;
    let value=segment;
    for(let pass=0;pass<5;pass++) {
      let next;
      try { next=decodeURIComponent(value); }
      catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
      if(next==='.'||next==='..') return fail('RESOURCE_PATH_DOT_SEGMENT');
      if(next.includes('/')||next.includes('\\')) return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
      if(next===value) break;
      value=next;
      if(pass===4) return fail('RESOURCE_PATH_ENCODING_DEPTH');
    }
  }
  let url;
  try { url=new URL(input); } catch { return fail('RESOURCE_URL_INVALID'); }
  if(!['http:','https:'].includes(url.protocol)) return fail('RESOURCE_URL_SCHEME');
  if(!url.hostname) return fail('RESOURCE_URL_HOST');
  if(url.username||url.password) return fail('RESOURCE_URL_USERINFO');
  return {ok:true,canonicalURL:url.href,url};
}

/** Bind a real resource path and optional echoed parameter claims to a template. */
function bindPath(template, actual, claimed) {
  const parts=template.split('/'), values=actual.split('/');
  if(parts.length!==values.length) return fail('TEMPLATE_PATH_MISMATCH');
  const bindings={};
  for(let i=1;i<parts.length;i++) {
    let value;
    try { value=decodeURIComponent(values[i]); }
    catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
    if(value.includes('/')||value.includes('\\')||value==='.'||value==='..') {
      return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
    }
    const p=PARAM.exec(parts[i]);
    if(p) {
      if(!value) return fail('TEMPLATE_EMPTY_PARAM');
      bindings[p[1]]=value;
    } else if(value!==parts[i]) {
      return fail('TEMPLATE_PATH_MISMATCH');
    }
  }
  if(claimed!==undefined) {
    if(claimed===null||Array.isArray(claimed)||typeof claimed!=='object') {
      return fail('TEMPLATE_PARAMS_INVALID');
    }
    const want=Object.keys(bindings).sort(),got=Object.keys(claimed).sort();
    if(JSON.stringify(want)!==JSON.stringify(got)) return fail('TEMPLATE_PARAMS_MISMATCH');
    for(const key of want) if(String(claimed[key])!==bindings[key]) {
      return fail('TEMPLATE_PARAMS_MISMATCH');
    }
  }
  return {ok:true,bindings};
}

/**
 * Input: {resourceURL, input:{type:'http',method,pathParams?} or
 * input:{type:'mcp',toolName}, routeTemplate?}.
 * Outputs an implementation-private catalogKey, NOT authentication.
 * Independently verify seller, payTo, schema, settlement before any write.
 */
export function resolveCatalogIdentity(record) {
  if(!record||typeof record!=='object') return {status:'rejected',reason:'RECORD_INVALID'};
  const resource=inspectResourceURL(record.resourceURL);
  if(!resource.ok) return {status:'rejected',reason:resource.reason};
  if(!record.input||typeof record.input!=='object') return {status:'rejected',reason:'INPUT_MISSING'};
  const {canonicalURL,url}=resource;
  if(record.input.type==='mcp') {
    const name=record.input.toolName;
    if(typeof name!=='string'||!/^[A-Za-z0-9_.\-]{1,128}$/.test(name)) {
      return {status:'rejected',reason:'MCP_TOOL_NAME_INVALID'};
    }
    return {status:'accepted',kind:'mcp',resourceURL:canonicalURL,
      catalogKey:'mcp|'+canonicalURL+'|'+name,toolName:name};
  }
  if(record.input.type!=='http'||!METHODS.has(record.input.method)) {
    return {status:'rejected',reason:'HTTP_METHOD_INVALID'};
  }
  const method=record.input.method;
  const concrete={status:'accepted',kind:'http',resourceURL:canonicalURL,
    catalogKey:'http|'+method+'|'+canonicalURL,method};
  if(record.routeTemplate===undefined||record.routeTemplate===null) return concrete;
  const template=inspectRouteTemplate(record.routeTemplate);
  if(!template.ok) return {...concrete,status:'fallback',reason:template.reason};
  const matched=bindPath(template.canonicalPath,url.pathname,record.input.pathParams);
  if(!matched.ok) return {...concrete,status:'fallback',reason:matched.reason};
  const keyURL=url.origin+template.canonicalPath;
  return {status:'accepted',kind:'http',resourceURL:keyURL,
    catalogKey:'http|'+method+'|'+keyURL,method,
    canonicalRouteTemplate:template.canonicalPath,pathParams:matched.bindings};
}

// MIT. Saved acquisition views of the original SF88/SF36 accounting authority.
import {constants} from 'node:fs';
import {lstat,mkdir,open,realpath} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {isAbsolute,join,resolve} from 'node:path';
import {config as nativeConfig,execution,need} from '../sf88-operator-buyer-cli/config.mjs';
import {openWorkspace} from '../sf88-operator-buyer-cli/workspace.mjs';
import {finalizeOriginalAttempt,readUnpaidAttempt,saveFinalizationView,
  summarizeFinalization} from '../sf88-operator-buyer-cli/finalization.mjs';

const SCHEMA='stellar-forge.buyer-runbook-accounting.v1';
const BINDING='stellar-forge.buyer-runbook-accounting-workspace.v1';
const FINAL=new Set(['FINALIZED','IDEMPOTENT_FINALIZED']);
const HASH=/^[a-f0-9]{64}$/;
const hash=raw=>createHash('sha256').update(raw).digest('hex');
const encode=value=>Buffer.from(JSON.stringify(value,null,2)+'\n');
const codeOf=error=>/^[A-Z0-9_]{1,120}$/.test(error?.code??'')?error.code:'RUNBOOK_ACCOUNTING_FAILED';
const root=plan=>join(plan.directory,'accounting');
const viewPath=(plan,row)=>join(root(plan),row.id+'.json');
const bindingPath=(plan,row)=>join(root(plan),row.id+'.workspace.json');
const own=info=>(info.mode&0o077)===0&&typeof process.getuid==='function'&&info.uid===process.getuid();

function planDigest(plan) { const {createdAt,...value}=plan;return hash(encode(value)); }
function identity(plan,row) {
  return {directory:plan.directory,planId:plan.id,planSha256:planDigest(plan),
    id:row.id,intentId:row.intentId,configSha256:row.config.sha256};
}
function matches(value,expected) {
  return value&&Object.entries(expected).every(([key,item])=>value[key]===item);
}
function atomic(value) {
  if(typeof value==='number')need(Number.isSafeInteger(value)&&value>=0,'RUNBOOK_ACCOUNTING_AMOUNT_INVALID');
  const text=String(value);
  need(/^(?:0|[1-9][0-9]{0,39})$/.test(text),'RUNBOOK_ACCOUNTING_AMOUNT_INVALID');
  return text;
}
async function directory(path,create=false) {
  need(typeof path==='string'&&isAbsolute(path)&&resolve(path)===path&&!path.includes('\0'),
    'RUNBOOK_ACCOUNTING_CANONICAL_PATH_REQUIRED');
  if(create)await mkdir(path,{mode:0o700}).catch(error=>{if(error.code!=='EEXIST')throw error;});
  const info=await lstat(path);
  need(info.isDirectory()&&!info.isSymbolicLink()&&own(info)&&await realpath(path)===path,
    'RUNBOOK_ACCOUNTING_PRIVATE_DIRECTORY_REQUIRED');
  return path;
}
async function read(path) {
  const file=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);
  try {
    const info=await file.stat();
    need(info.isFile()&&own(info)&&info.size<=4_000_000,'RUNBOOK_ACCOUNTING_PRIVATE_FILE_REQUIRED');
    const raw=await file.readFile();
    need(raw.length<=4_000_000,'RUNBOOK_ACCOUNTING_FILE_TOO_LARGE');
    return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));
  } finally {await file.close();}
}
async function optional(path) {try{return await read(path);}catch(error){if(error.code==='ENOENT')return null;throw error;}}
async function binding(plan,row) {
  const value=await optional(bindingPath(plan,row));
  if(value)need(value.schema===BINDING&&matches(value,identity(plan,row))&&
    typeof value.workspace==='string'&&isAbsolute(value.workspace)&&resolve(value.workspace)===value.workspace,
    'RUNBOOK_ACCOUNTING_WORKSPACE_CHANGED');
  return value;
}
function validateResult(result,row) {
  need(FINAL.has(result?.outcome)&&result.request_id===row.intentId&&HASH.test(result.request_sha256??'')&&
    typeof result.receipt_ref==='string'&&result.receipt_ref.startsWith(row.acceptedCaps.network+'/'),
    'RUNBOOK_ACCOUNTING_RESULT_CHANGED');
  atomic(result.actual);
}
async function savedView(plan,row) {
  const value=await optional(viewPath(plan,row));
  if(value) {
    need(value.schema===SCHEMA&&matches(value,identity(plan,row))&&value.attemptStartedAt===row.started?.at,
      'RUNBOOK_ACCOUNTING_VIEW_CHANGED');
    if(FINAL.has(value.result?.outcome))validateResult(value.result,row);
    if(value.lastFinalized)validateResult(value.lastFinalized.result,row);
    if(value.unsignedResponse)need(value.unsignedResponse.outcome==='NO_PAYMENT_REQUIRED'&&
      value.unsignedResponse.receipt===null&&value.unsignedResponse.actualAtomicUnits===null,
      'RUNBOOK_ACCOUNTING_VIEW_CHANGED');
  }
  return value;
}
function summarize(view,row,selected) {
  const summary=view?.unsignedResponse??summarizeFinalization(view);
  const final=FINAL.has(view?.result?.outcome)?{completedAt:view.completedAt,result:view.result}:view?.lastFinalized;
  const finalized=final?{outcome:final.result.outcome,completedAt:final.completedAt,
    actualAtomicUnits:atomic(final.result.actual),receipt:final.result.receipt_ref,
    requestSha256:final.result.request_sha256}:null;
  return {...summary,outcome:view?.observationError?'OBSERVATION_FAILED':summary.outcome,
    workspace:selected?.workspace??view?.workspace??null,
    workspaceSource:selected?.source??null,finalized,
    viewStatus:view?'SAVED':'NOT_RECORDED',
    lastError:view?.observationError??null,checkedAt:view?.completedAt??null,
    evidenceSha256:view?.evidenceSha256??null,
    recordAuthority:view?.unsignedResponse?.recordAuthority??'ORIGINAL_SF36_LEDGER; SAVED_ACQUISITION_VIEW',
    attempted:row.state!=='UNATTEMPTED'};
}

/** Read saved views only; this neither observes a network nor opens a wallet. */
export async function inspectAcquisitionAccounting(state) {
  let exists=true;
  try{await directory(root(state.plan));}catch(error){if(error.code==='ENOENT')exists=false;else throw error;}
  const operations=[];
  for(const row of state.operations) {
    let accounting;
    try {
      const selected=exists?await binding(state.plan,row):null;
      const view=exists?await savedView(state.plan,row):null;
      accounting=summarize(view,row,selected);
    } catch(error) {
      accounting={outcome:'SAVED_VIEW_UNAVAILABLE',viewStatus:'READ_FAILED',lastError:codeOf(error),
        workspace:null,finalized:null,attempted:row.state!=='UNATTEMPTED'};
    }
    operations.push({...row,accounting});
  }
  const groups=new Map();
  for(const row of operations) {
    const key=JSON.stringify([row.acceptedCaps.network,row.acceptedCaps.asset]);
    let group=groups.get(key);
    if(!group){group={network:row.acceptedCaps.network,asset:row.acceptedCaps.asset,operations:0,
      plannedMaximumAtomic:'0',finalizedActualAtomic:'0',finalizedOperations:0,
      unsignedOperations:0,unresolvedOperations:0,unattemptedOperations:0};groups.set(key,group);}
    group.operations++;
    group.plannedMaximumAtomic=(BigInt(group.plannedMaximumAtomic)+BigInt(row.acceptedCaps.maxAtomic)).toString();
    if(row.accounting.finalized){group.finalizedOperations++;
      group.finalizedActualAtomic=(BigInt(group.finalizedActualAtomic)+BigInt(row.accounting.finalized.actualAtomicUnits)).toString();}
    else if(row.accounting.outcome==='NO_PAYMENT_REQUIRED')group.unsignedOperations++;
    else if(row.state==='UNATTEMPTED')group.unattemptedOperations++;
    else group.unresolvedOperations++;
  }
  return {...state,operations,accounting:{schema:SCHEMA,groups:[...groups.values()],
    meaning:'Actual totals include each retained original finalized receipt once. Unsigned, unresolved and untouched operations retain separate counts. Network and asset amounts are never converted or combined.',
    finalizedOperations:operations.filter(row=>row.accounting.finalized).length,
    unsignedOperations:operations.filter(row=>!row.accounting.finalized&&row.accounting.outcome==='NO_PAYMENT_REQUIRED').length,
    unresolvedOperations:operations.filter(row=>row.state!=='UNATTEMPTED'&&!row.accounting.finalized&&row.accounting.outcome!=='NO_PAYMENT_REQUIRED').length}};
}

/** Check the retained configuration without rereading a previously spent body. */
async function frozenConfiguration(plan,row) {
  const cfgPath=join(plan.directory,'configs',row.id+'.json');
  await directory(join(plan.directory,'configs'));
  const file=await open(cfgPath,constants.O_RDONLY|constants.O_NOFOLLOW);
  let raw;
  try {const info=await file.stat();need(info.isFile()&&own(info)&&info.size<=65536,'RUNBOOK_ACCOUNTING_CONFIG_INVALID');
    raw=await file.readFile();need(raw.length<=65536&&hash(raw)===row.config.sha256,'FROZEN_CONFIG_CHANGED');}
  finally {await file.close();}
  const cfg=await nativeConfig(cfgPath),{op,owner,download}=execution(cfg);
  need(JSON.stringify(cfg)===JSON.stringify(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw))),
    'FROZEN_CONFIG_CHANGED');
  need(row.config.path==='configs/'+row.id+'.json'&&op.intentId===row.intentId&&op.url===row.url&&
    op.method===row.method&&JSON.stringify(op.expect)===JSON.stringify(row.acceptedCaps)&&
    JSON.stringify(op.headers)===JSON.stringify(row.headers)&&owner.actor===row.actor&&owner.service===row.service&&
    cfg.evidenceDir===row.evidenceDirectory&&JSON.stringify(download)===JSON.stringify(row.responseFile),
    'FROZEN_PLAN_MISMATCH');
  need(row.body?row.body.path==='bodies/'+row.id+'.bin'&&op.bodyFile===join(plan.directory,row.body.path)&&
    HASH.test(row.body.sha256??'')&&Number.isSafeInteger(row.body.bytes)&&row.body.bytes>=0:
    op.bodyFile===undefined,'FROZEN_BODY_CHANGED');
  return cfg;
}

/** Bind an existing original operator. Its current ledger, payer and network
 * must match the frozen config; no signer code or spending key is loaded. */
async function originalWorkspace(plan,row,path) {
  path=await directory(path);
  const cfg=await frozenConfiguration(plan,row),native=await openWorkspace(['--dir',path]);
  const {owner,transport,op}=execution(cfg),other=execution(native.config);
  need(op.intentId===row.intentId&&cfg.evidenceDir===row.evidenceDirectory&&
    ['python','actor','service','policy','ledger'].every(key=>owner[key]===other.owner[key])&&
    cfg.signerModule===native.config.signerModule&&cfg.trustedPayer===native.config.trustedPayer&&
    cfg.evidenceDir===native.config.evidenceDir&&JSON.stringify(transport)===JSON.stringify(other.transport)&&
    ['scheme','network','asset','payTo'].every(key=>op.expect[key]===other.op.expect[key]),
    'RUNBOOK_ACCOUNTING_ORIGINAL_WORKSPACE_REQUIRED');
  return native.manifest.directory;
}
export async function bindAcquisitionWorkspace(plan,row,workspace,{source='OPERATOR_SELECTED'}={}) {
  need(['OPERATOR_SELECTED','RECEIVED_ORIGINAL_OPERATOR'].includes(source),'RUNBOOK_ACCOUNTING_BINDING_SOURCE_INVALID');
  const selected=await originalWorkspace(plan,row,workspace);
  await directory(root(plan),true);
  const previous=await binding(plan,row);
  const value={schema:BINDING,...identity(plan,row),workspace:selected,source,
    selectedAt:previous?.workspace===selected?previous.selectedAt:new Date().toISOString()};
  await saveFinalizationView(bindingPath(plan,row),value);
  return value;
}

/** One already performed original attempt. The caller holds the runbook lease.
 * No buyer execution, reservation, signer import or payment is initiated here. */
export async function finalizeAcquisitionOperation(plan,row,{workspace,workspaceSource,workspaceForOperation,
  signal,outbox,merchantRoute}={}) {
  need(row.started?.schema==='stellar-forge.buyer-runbook-started.v1'&&row.started.id===row.id&&
    row.started.intentId===row.intentId&&row.started.configSha256===row.config.sha256&&
    typeof row.started.at==='string'&&Number.isFinite(Date.parse(row.started.at)),
    'RUNBOOK_ACCOUNTING_ORIGINAL_ATTEMPT_REQUIRED');
  await directory(root(plan),true);
  const previous=await savedView(plan,row),oldBinding=await binding(plan,row);
  const evidencePath=join(row.evidenceDirectory,hash(row.intentId)+'.json');
  const base={schema:SCHEMA,...identity(plan,row),attemptStartedAt:row.started.at,
    bodySha256:row.body?.sha256??null,bodyBytes:row.body?.bytes??0,evidencePath,
    recordAuthority:'ORIGINAL_SF36_LEDGER; THIS_FILE_IS_A_SAVED_ACQUISITION_VIEW'};
  let view,selected=oldBinding;
  try {
    need(!signal?.aborted,'RUNBOOK_ACCOUNTING_INTERRUPTED');
    await frozenConfiguration(plan,row);
    need(!row.result?.summary?.evidencePath||row.result.summary.evidencePath===evidencePath,
      'RUNBOOK_ACCOUNTING_EVIDENCE_PATH_CHANGED');
    const unsigned=await readUnpaidAttempt({evidencePath,intentId:row.intentId,attemptStartedAt:row.started.at});
    if(unsigned) {
      need(!previous?.lastFinalized&&!FINAL.has(previous?.result?.outcome),'RUNBOOK_ACCOUNTING_UNPAID_CONFLICT');
      view={...base,unsignedResponse:unsigned,completedAt:new Date().toISOString()};
    } else {
      const automatic=workspace===undefined&&!oldBinding&&workspaceForOperation?
        await workspaceForOperation(row):null;
      const target=workspace??oldBinding?.workspace??automatic;
      need(target,'RUNBOOK_ACCOUNTING_WORKSPACE_REQUIRED');
      selected=await bindAcquisitionWorkspace(plan,row,target,{source:workspaceSource??oldBinding?.source??
        (automatic?'RECEIVED_ORIGINAL_OPERATOR':'OPERATOR_SELECTED')});
      const finalized=await finalizeOriginalAttempt({configurationPath:join(plan.directory,'configs',row.id+'.json'),
        configSha256:row.config.sha256,intentId:row.intentId,evidencePath,
        bodySha256:row.body?.sha256??null,bodyBytes:row.body?.bytes??0,
        attemptStartedAt:row.started.at,workspace:selected.workspace,signal,outbox,merchantRoute});
      view={...base,...finalized};
      if(FINAL.has(view.result.outcome)){validateResult(view.result,row);
        view.lastFinalized={completedAt:view.completedAt,result:view.result};}
    }
  } catch(error) {
    view={...base,workspace:selected?.workspace??null,completedAt:new Date().toISOString(),observationError:codeOf(error)};
  }
  if(!view.lastFinalized) {
    if(previous?.lastFinalized)view.lastFinalized=previous.lastFinalized;
    else if(FINAL.has(previous?.result?.outcome))view.lastFinalized={completedAt:previous.completedAt,result:previous.result};
  }
  let viewStatus='SAVED',saveError;
  try {await saveFinalizationView(viewPath(plan,row),view);}
  catch(error){viewStatus='SAVE_FAILED';saveError=codeOf(error);}
  return {id:row.id,intentId:row.intentId,...summarize(view,row,selected),viewStatus,
    ...(saveError?{saveError}:{}),status:view.observationError?'OBSERVATION_FAILED':
      view.unsignedResponse?.outcome??view.result?.outcome??'NOT_RECORDED'};
}

// Recovery reads the same original binding without creating an accounting selection.
export {originalWorkspace as inspectAcquisitionWorkspace};

// MIT. Offline industrial operator report; no scripts, external resources or forms.
const escape = value => String(value ?? '').replace(/[&<>"']/g, character =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const code = value => `<code>${escape(value ?? '—')}</code>`;
const json = value => escape(JSON.stringify(value, null, 2));

function nextAction(row) {
  if (row.integrity !== 'UNCHANGED') return 'Restore the recorded config or body snapshot from its original input, or initialize a separate reviewed plan. Existing attempts remain recorded.';
  if (row.state === 'UNATTEMPTED') return row.lastError ?
    'Resolve the displayed local setup problem, then execute this runbook to continue this untouched operation.' :
    'Execute this runbook when ready. The original buyer obtains fresh seller terms and uses its original terminal approval.';
  if (row.state === 'INTERRUPTED_NO_RESULT') return 'Use recover to import any complete original SF88 output. Inspect the retained output, native evidence and original governor reservation for this intent before selecting any further action.';
  if (row.state === 'NOT_LAUNCHED') return 'The native process was not launched. Fix the launch error; the saved native config remains available for a separately selected original SF88 operation. This runbook keeps its recorded attempt.';
  if (row.state === 'NO_COMPLETE_NATIVE_RESULT') return 'Inspect the original stdout/stderr, evidence directory and governor ledger using the same intent ID. The runbook will continue untouched jobs without purchasing this operation again.';
  const summary = row.result?.summary;
  if (summary?.error || summary?.evidenceError || summary?.responseFile?.status === 'FAILED')
    return 'Use the original buyer/evidence error and any saved or partial output below to resolve this operation. Other untouched jobs can continue. A file failure does not cancel a payment.';
  return row.accounting?.finalized?'Use the returned resource and retained original accounting receipt. A later accounting refresh reuses the same original ledger.':
    'Refresh accounting in this acquisition or with the finalize command. Select this request’s existing original operator workspace if it was not received here.';
}

function accounting(row) {
  const value=row.accounting,final=value?.finalized;
  if(!value)return '';
  return `<section class="result"><h3>Original accounting</h3><dl class="terms"><div><dt>Latest check</dt><dd>${code(value.outcome)} · ${escape(value.checkedAt??'Not checked')}</dd></div><div><dt>Original operator</dt><dd>${code(value.workspace)}</dd></div><div><dt>Finalized actual atomic units</dt><dd>${final?code(final.actualAtomicUnits):'Awaiting original finalization'}</dd></div><div><dt>Receipt</dt><dd>${code(final?.receipt)}</dd></div>${final?`<div><dt>Finalized request digest</dt><dd>${code(final.requestSha256)}</dd></div><div><dt>Receipt retained at</dt><dd>${escape(final.completedAt)}</dd></div>`:''}</dl>${value.lastError?`<p class="notice">Latest accounting condition: ${code(value.lastError)}. An earlier finalized receipt remains included when present.</p>`:''}${value.outcome==='NO_PAYMENT_REQUIRED'?'<p>This is the original unsigned response; it carries no ledger receipt or actual payment amount.</p>':''}</section>`;
}

/** Accounting CSV is a view of existing original results, one operation per row. */
export function renderAccountingCSV(state) {
  const cell=value=>{
    let text=String(value??'');
    if(/^[\s]*[=+@-]/.test(text))text="'"+text;
    return '"'+text.replaceAll('"','""')+'"';
  };
  const rows=[['operation_id','label','intent_id','network','asset','request_ceiling_atomic',
    'finalized_actual_atomic','receipt','finalized_request_sha256','receipt_completed_at',
    'latest_accounting_outcome','latest_check_at','latest_error','buyer_state','buyer_status','delivery_status']];
  for(const row of state.operations){const value=row.accounting,final=value?.finalized;
    rows.push([row.id,row.label,row.intentId,row.acceptedCaps.network,row.acceptedCaps.asset,row.acceptedCaps.maxAtomic,
      final?.actualAtomicUnits,final?.receipt,final?.requestSha256,final?.completedAt,value?.outcome,value?.checkedAt,
      value?.lastError,row.state,row.result?.summary?.status,row.result?.summary?.responseFile?.status]);}
  return rows.map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';
}

function accountingTotals(state) {
  if(!state.accounting)return '';
  return `<section class="panel"><h2>Accounting and receipts</h2><p class="muted">${escape(state.accounting.meaning)}</p><div class="table"><table><thead><tr><th>Network / asset</th><th>Finalized atomic units</th><th>Finalized</th><th>Unsigned</th><th>Unresolved</th><th>Untouched</th></tr></thead><tbody>${state.accounting.groups.map(group=>`<tr><td>${code(group.network)}<br>${code(group.asset)}</td><td>${code(group.finalizedActualAtomic)}</td><td>${group.finalizedOperations}</td><td>${group.unsignedOperations}</td><td>${group.unresolvedOperations}</td><td>${group.unattemptedOperations}</td></tr>`).join('')}</tbody></table></div></section>`;
}

function job(row) {
  const summary = row.result?.summary, delivery = summary?.responseFile;
  const terms = row.acceptedCaps;
  return `<article id="${escape(row.id)}">
  <div class="heading"><div><p class="eyebrow">${escape(row.id)} · ${escape(row.state)}</p><h2>${escape(row.label)}</h2></div><span class="state">${escape(row.integrity)}</span></div>
  <p class="resource">${code(row.method)} ${code(row.url)}</p>
  <dl class="terms"><div><dt>Intent</dt><dd>${code(row.intentId)}</dd></div><div><dt>Actor / service</dt><dd>${code(row.actor)} / ${code(row.service)}</dd></div><div><dt>Network / scheme</dt><dd>${code(terms.network)} / ${code(terms.scheme)}</dd></div><div><dt>Maximum atomic units</dt><dd>${code(terms.maxAtomic)}</dd></div><div><dt>Asset</dt><dd>${code(terms.asset)}</dd></div><div><dt>Recipient</dt><dd>${code(terms.payTo)}</dd></div><div><dt>Timeout ceiling</dt><dd>${terms.maxTimeoutSeconds === undefined ? 'No additional caller ceiling' : escape(terms.maxTimeoutSeconds) + ' seconds'}</dd></div><div><dt>Payment flow</dt><dd>${escape(terms.paymentFlow ?? 'Original buyer selection')}</dd></div><div><dt>Request body</dt><dd>${row.body ? `${row.body.bytes.toLocaleString('en-US')} bytes · ${code(row.body.sha256)}` : 'Absent'}</dd></div><div><dt>Output destination</dt><dd>${code(row.responseFile?.destination)}</dd></div></dl>
  <p class="action">${escape(nextAction(row))}</p>
  ${row.lastError ? `<p class="notice">Local setup: ${code(row.lastError.code)}</p>` : ''}
  ${row.integrityError ? `<p class="notice">Input: ${code(row.integrityError)}</p>` : ''}
  ${summary ? `<div class="result"><h3>Original buyer result</h3><dl class="terms"><div><dt>Buyer / HTTP status</dt><dd>${code(summary.status)} / ${code(summary.httpStatus)}</dd></div><div><dt>Native process exit</dt><dd>${row.result.recovered ? 'Recovered result; process exit not observed' : code(row.result.exitCode)}</dd></div><div><dt>Local file</dt><dd>${code(delivery?.status ?? 'NOT_REQUESTED')}${delivery?.bytes !== undefined ? ` · ${escape(delivery.bytes)} bytes` : ''}</dd></div><div><dt>Native evidence</dt><dd>${code(summary.evidencePath)}</dd></div><div><dt>Saved output</dt><dd>${code(delivery?.path ?? delivery?.destination)}</dd></div><div><dt>Partial output</dt><dd>${code(delivery?.partialPath)}</dd></div></dl>
  ${row.downloadName && delivery?.status === 'SAVED' ? `<p><a href="downloads/${encodeURIComponent(row.downloadName)}" download="${escape(row.downloadName)}">Download ${escape(row.downloadName)}</a></p>` : ''}
  <details><summary>Original SF88 summary</summary><pre>${json(summary)}</pre></details></div>` : ''}
  ${accounting(row)}
