/** Current state is reconstructed from immutable attempts, never HTTP guesses. */
export async function inspectRunbook(directory) {
  const plan = await readPlan(directory), rows = [];
  const lease = await latestLease(plan.directory);
  const executionLock = lease && !await wasReleased(plan.directory, lease) ? lease : null;
  for (const op of plan.operations) {
    const started = await recordAt(startedPath(plan.directory, op.id));
    const result = await finalRecord(plan.directory, op);
    const lastError = await recordAt(join(plan.directory, 'attempts', op.id + '.last-error.json'));
    let integrity = 'UNCHANGED', integrityError = null;
    try { await nativeInput(plan, op); }
    catch (error) { integrity = 'INPUT_CHANGED_OR_UNAVAILABLE'; integrityError = codeOf(error); }
    rows.push({...op, state:result?.state ?? (await attempted(plan.directory, op.id) ? 'INTERRUPTED_NO_RESULT' : 'UNATTEMPTED'),
      integrity, integrityError, started, result, lastError:result ? null : lastError });
  }
  return inspectAcquisitionAccounting({schema:'stellar-forge.buyer-runbook-status.v1', inspectedAt:now(), plan,
    executionLock:executionLock ? {pid:executionLock.pid, generation:executionLock.generation, host:executionLock.host, startedAt:executionLock.startedAt,
      ownerRunning:executionLock.host === hostname() ? await alive(executionLock.pid, executionLock.processToken) : null} : null,
    operations:rows});
}

/** Select an existing original accounting workspace for one frozen operation. */
export async function bindRunbookWorkspace(directory,{only,workspace}={}) {
  const plan=await readPlan(directory),row=plan.operations.find(op=>op.id===only);
  need(row,'UNKNOWN_JOB_ID');
  const release=await acquireExecutionLease(plan.directory);
  try {return await bindAcquisitionWorkspace(plan,row,workspace);}
  finally {await release();}
}

/** Complete existing attempts serially through original SF88/SF36. The same
 * immutable run lease excludes execution/recovery and other accounting owners. */
export async function finalizeRunbook(directory,{only,workspace,workspaceForOperation,signal,
  outbox,merchantRoute,onProgress=()=>{}}={}) {
  need(signal===undefined||signal instanceof AbortSignal,'INVALID_ABORT_SIGNAL');
  need(workspaceForOperation===undefined||typeof workspaceForOperation==='function',
    'INVALID_ACCOUNTING_WORKSPACE_RESOLVER');
  need(Boolean(outbox)===Boolean(merchantRoute),'OUTBOX_AND_ORIGINAL_MERCHANT_ROUTE_REQUIRED_TOGETHER');
  need(!outbox||only!==undefined,'RUNBOOK_OUTBOX_REQUIRES_SELECTED_OPERATION');
  const plan=await readPlan(directory);
  need(only===undefined||plan.operations.some(op=>op.id===only),'UNKNOWN_JOB_ID');
  const release=await acquireExecutionLease(plan.directory),results=[];
  try {
    const state=await inspectRunbook(plan.directory);
    need(runbookPlanDigest(state.plan)===runbookPlanDigest(plan),'FROZEN_PLAN_MISMATCH');
    for(const row of state.operations) {
      if(only!==undefined&&row.id!==only)continue;
      if(signal?.aborted)break;
      if(row.state==='UNATTEMPTED'){results.push({id:row.id,status:'UNATTEMPTED'});continue;}
      onProgress({id:row.id,status:'CHECKING_ORIGINAL_ACCOUNTING'});
      let result;
      try {result=await finalizeAcquisitionOperation(plan,row,{workspace,workspaceForOperation,signal,outbox,merchantRoute});}
      catch(error){result={id:row.id,status:'ACCOUNTING_PREFLIGHT_FAILED',code:codeOf(error)};}
      results.push(result);onProgress({id:row.id,status:result.status,
        ...(result.lastError||result.code?{code:result.lastError??result.code}:{}),viewStatus:result.viewStatus});
    }
  } finally {await release();}
  return {schema:'stellar-forge.buyer-runbook-accounting-refresh.v1',results,interrupted:signal?.aborted===true};
}

export async function saveRunbookReport(directory) {
  const state = await inspectRunbook(directory);
  const { renderReport,renderAccountingCSV } = await import('./report.mjs');
  await replaceFile(join(state.plan.directory, 'status.json'), serialized(state));
  await replaceFile(join(state.plan.directory, 'report.html'), Buffer.from(renderReport(state)));
  await replaceFile(join(state.plan.directory,'accounting.csv'),Buffer.from(renderAccountingCSV(state)));
  return {state, reportPath:join(state.plan.directory, 'report.html'), statusPath:join(state.plan.directory, 'status.json'),
    accountingPath:join(state.plan.directory,'accounting.csv')};
}

// MIT. One static asset contract for the maintained HTTP server and source archive.
import { readFile } from 'node:fs/promises';
import { posix } from 'node:path';

const ORIGIN = 'https://starforge.invalid';
const SCHEMA = 'stellar-forge.browser-assets.v1';

function relativeFile(value, label) {
  if (typeof value !== 'string' || !value || value.startsWith('/') ||
      /[\u0000-\u0020\u007f\\?#%:]/.test(value))
    throw new TypeError('Invalid browser asset ' + label);
  return value;
}

function repositoryFile(value, label) {
  relativeFile(value, label);
  if (posix.normalize(value) !== value || value === '..' || value.startsWith('../'))
    throw new TypeError('Browser asset leaves its repository: ' + label);
  return value;
}

export function parseBrowserAssets(input) {
  const spec = JSON.parse(input);
  if (!spec || spec.schema !== SCHEMA || !Array.isArray(spec.routes) || !spec.routes.length)
    throw new TypeError('Unsupported browser asset manifest');
  relativeFile(spec.root, 'root');
  if (!spec.root.endsWith('/')) throw new TypeError('Browser asset root must be a directory');
  const paths = new Set();
  const routes = spec.routes.map(entry => {
    if (!Array.isArray(entry) || entry.length !== 2 || !Array.isArray(entry[1]) || entry[1].length !== 2)
      throw new TypeError('Browser asset route must contain a path, file and content type');
    const [path, [file, type]] = entry;
    if (typeof path !== 'string' || !path.startsWith('/') || path.startsWith('//') ||
        /[\u0000-\u0020\u007f\\?#%]/.test(path) ||
        new URL(path, ORIGIN).pathname !== path || paths.has(path))
      throw new TypeError('Invalid or duplicate browser asset route: ' + path);
    relativeFile(file, 'file');
    if (file.endsWith('/') || typeof type !== 'string' || !type || /[\r\n\u0000]/.test(type))
      throw new TypeError('Invalid browser asset file or content type: ' + path);
    paths.add(path);
    return [path, { file, type }];
  });
  return { root: spec.root, routes };
}

export async function readBrowserAssets(manifestUrl) {
  const url = new URL(manifestUrl);
  if (url.protocol !== 'file:' || url.search || url.hash)
    throw new TypeError('Browser assets require a local manifest URL');
  const spec = parseBrowserAssets(await readFile(url, 'utf8'));
  const root = new URL(spec.root, url);
  return new Map(spec.routes.map(([path, { file, type }]) =>
    [path, { url: new URL(file, root), type }]));
}

// readSource must return bytes from the same immutable source selection. Server,
// manifest and every mapped file remain ordinary, separately hashed source files.
export function createBrowserAssetIndex(registrations, readSource) {
  if (!Array.isArray(registrations) || typeof readSource !== 'function')
    throw new TypeError('Browser assets require registrations and a source reader');
  const servers = new Set(), files = new Set(), contexts = new Map();
  for (const registration of registrations) {
    if (!registration || typeof registration !== 'object' || Array.isArray(registration))
      throw new TypeError('Invalid browser asset registration');
    const server = repositoryFile(registration.server, 'server');
    const manifest = repositoryFile(registration.manifest, 'manifest');
    if (servers.has(server)) throw new TypeError('Duplicate browser asset server: ' + server);
    servers.add(server);
    readSource(server);
    const spec = parseBrowserAssets(readSource(manifest));
    const routes = new Map(spec.routes.map(([path, { file }]) =>
      [path, repositoryFile(posix.join(posix.dirname(manifest), spec.root, file), manifest + ' -> ' + file)]));
    for (const [route, file] of routes) {
      files.add(file);
      const entries = contexts.get(file) ?? [];
      entries.push({ server, manifest, route, routes });
      contexts.set(file, entries);
    }
  }
  return {
    files: [...files],
    resolve(importer, request) {
      const entries = contexts.get(importer);
      if (!entries || !request.startsWith('.') && !request.startsWith('/')) return null;
      const targets = new Set();
      for (const { server, manifest, route, routes } of entries) {
        const url = new URL(request, new URL(route, ORIGIN));
        const target = url.origin === ORIGIN && !url.search ? routes.get(url.pathname) : undefined;
        if (!target)
          throw new TypeError('Unserved browser module: ' + importer + ' -> ' + request +
            ' at ' + route + ' (' + server + '; ' + manifest + ')');
        targets.add(target);
      }
      return [...targets];
    },
  };
}

